// Package postgres provides the Postgres implementation of the service
// stores. Queries are generated by sqlc from db/queries, so a mismatch with
// the schema is caught at compile time.
package postgres

import (
	"context"
	"errors"
	"fmt"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/benja/todo-api/internal/db"
	"github.com/benja/todo-api/internal/domain"
	"github.com/benja/todo-api/internal/service"
)

// TodoStore implements service.TodoStore backed by Postgres.
type TodoStore struct {
	q *db.Queries
}

// Compile-time check: *TodoStore satisfies the consumer-side interface.
var _ service.TodoStore = (*TodoStore)(nil)

// NewTodoStore builds a store backed by a pgx connection pool.
func NewTodoStore(pool *pgxpool.Pool) *TodoStore {
	return &TodoStore{q: db.New(pool)}
}

// List returns every todo, newest first.
func (s *TodoStore) List(ctx context.Context) ([]domain.Todo, error) {
	rows, err := s.q.ListTodos(ctx)
	if err != nil {
		return nil, fmt.Errorf("list todos: %w", err)
	}

	todos := make([]domain.Todo, 0, len(rows))
	for _, row := range rows {
		todos = append(todos, toDomain(row))
	}
	return todos, nil
}

// Get returns a todo by ID.
func (s *TodoStore) Get(ctx context.Context, id string) (domain.Todo, error) {
	uid, err := parseID(id)
	if err != nil {
		return domain.Todo{}, err
	}

	row, err := s.q.GetTodo(ctx, uid)
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.Todo{}, domain.ErrNotFound
	}
	if err != nil {
		return domain.Todo{}, fmt.Errorf("get todo: %w", err)
	}
	return toDomain(row), nil
}

// Create inserts a new todo.
func (s *TodoStore) Create(ctx context.Context, title string) (domain.Todo, error) {
	row, err := s.q.CreateTodo(ctx, title)
	if err != nil {
		return domain.Todo{}, fmt.Errorf("create todo: %w", err)
	}
	return toDomain(row), nil
}

// Update replaces the mutable fields of a todo.
func (s *TodoStore) Update(ctx context.Context, t domain.Todo) (domain.Todo, error) {
	uid, err := parseID(t.ID)
	if err != nil {
		return domain.Todo{}, err
	}

	row, err := s.q.UpdateTodo(ctx, db.UpdateTodoParams{
		ID:        uid,
		Title:     t.Title,
		Completed: t.Completed,
	})
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.Todo{}, domain.ErrNotFound
	}
	if err != nil {
		return domain.Todo{}, fmt.Errorf("update todo: %w", err)
	}
	return toDomain(row), nil
}

// Delete removes a todo; it returns domain.ErrNotFound when it did not exist.
func (s *TodoStore) Delete(ctx context.Context, id string) error {
	uid, err := parseID(id)
	if err != nil {
		return err
	}

	rows, err := s.q.DeleteTodo(ctx, uid)
	if err != nil {
		return fmt.Errorf("delete todo: %w", err)
	}
	if rows == 0 {
		return domain.ErrNotFound
	}
	return nil
}

// parseID converts a wire ID to a uuid, mapping malformed IDs to
// domain.ErrInvalidID.
func parseID(id string) (uuid.UUID, error) {
	uid, err := uuid.Parse(id)
	if err != nil {
		return uuid.Nil, fmt.Errorf("%w: %q", domain.ErrInvalidID, id)
	}
	return uid, nil
}

// toDomain maps a generated row into the domain entity so sqlc types do
// not leak past the store boundary.
func toDomain(row db.Todo) domain.Todo {
	return domain.Todo{
		ID:        row.ID.String(),
		Title:     row.Title,
		Completed: row.Completed,
		CreatedAt: row.CreatedAt,
		UpdatedAt: row.UpdatedAt,
	}
}
